os:store.os:value:
#[{
	acuerdoId: vars.responseAZSign.AcuerdoRsp.AcuerdoId,
	container : payload.documento[0].contenidoDocumento,
	fileName : payload.documento[0].nombreDocumento,
	usuario: payload.usuario
}]

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
if(vars.error)
{
	codigo: "500",
	descripcionRespuesta: "Error: Se envío email pero hubo un error al insertar el acuerdo: " ++ vars.responseAZSign.AcuerdoRsp.AcuerdoId
}
else
{
	codigo: "200" ,
	numeroAcuerdo: vars.responseAZSign.AcuerdoRsp.AcuerdoId,
	descripcionRespuesta: "Exitoso"
}
